import streamlit as stimport pandas as pdimport altair as altcol1, col2 = st.columns([1, 5])with col1:    st.image("logo.png", width=80)with col2:    st.markdown("<h1>⚽ FIFA World Cup 2026 ⚽</h1>", unsafe_allow_html=True)# Sidebarpage = st.sidebar.selectbox("Izaberi stranicu:", ["Poredak", "Prethodni osvajači", "Početne predikcije", "Popis igrača po reprezentacijama", "Kolo 1", "Kolo 2", "Kolo 3"])if page == "Poredak":    df = pd.read_csv("players.csv", header=None, encoding='utf-8-sig')    df.columns = ["**Igrači**", "**Bodovi**"]    df = df.sort_values("**Bodovi**", ascending=False).reset_index(drop=True)        df.index = df.index + 1        st.markdown("<h3 style='text-align: center;'>🏆 Poredak uživo</h3>", unsafe_allow_html=True)    # --- Centriraj i prikaži statičnu tablicu ---    df_styled = df.style.set_properties(**{'text-align': 'center'})    st.table(df_styled)    df_hist = pd.read_csv("history.csv")# --- lider ---    last_round = df_hist["Kolo"].max()    df_last = df_hist[df_hist["Kolo"] == last_round]    leader = df_last.loc[df_last["Bodovi"].idxmax(), "Igrač"]# --- selekcija ---    selection = alt.selection_point(fields=['Igrač'], bind='legend')# --- linije ---    chart = alt.Chart(df_hist).mark_line(point=True).encode(        x=alt.X('Kolo:O', title='Kolo', axis=alt.Axis(labelAngle=0)),        y=alt.Y('Bodovi:Q', title='Bodovi'),        color='Igrač:N',        strokeWidth=alt.condition(            alt.datum.Igrač == leader,            alt.value(4),            alt.value(2)        ),        opacity=alt.condition(selection, alt.value(1), alt.value(0.1)),        tooltip=['Igrač', 'Kolo', 'Bodovi']    ).add_params(        selection    )# --- zadnje točke ---    last_points = df_hist.sort_values("Kolo").groupby("Igrač").tail(1)# --- tekst na kraju linije ---    text_layer = alt.Chart(last_points).mark_text(        align='left',        dx=5    ).encode(        x='Kolo:O',        y='Bodovi:Q',        text='Igrač',        color='Igrač:N'    )# --- kombinacija ---    final_chart = chart + text_layer    st.markdown("### 📈 Grafički prikaz bodova po kolima (trenutno proba)")    st.altair_chart(final_chart, use_container_width=True)                    with st.expander("📜 Pravila"):        st.write("""        - Pogođen prvak: **8 bodova**          - Pogođen viceprvak: **6 bodova**        - Pogođen trećeplasirani: **4 boda**        - Pogođen igrač s najviše postignutih golova: **5 bodova**        - Pogođen igrač s najviše asistencija: **5 bodova**        - Pogođen najbolji igrač turnira: **5 bodova**        - Pogođen najbolji golman turnira: **5 bodova**        - Pogođena reprezentacija koja osvaja grupnu fazu: **3 boda**        - Pogođena reprezentacija koja prolazi dalje kao druga u grupi: **3 boda**        - U slučaju pogođenog prolaska obe ekipe u grupnoj fazi, ali obrnutim redosledom: **2 boda (bod za svaku ekipu)**        - Pogođen igrač koji osvaja takmičenje između nas: **5 bodova (dozvoljeno klađenje na samoga sebe)**        - Pogođen ishod uatkmice (1, x, 2): **2 boda**        - U slučaju da pogođeni igrač s najviše postignutih golova/asistencija deli prvo mesto s nekim drugim igračem: **2 boda**        - Svoje tipove šaljete 24h prije početka prve utakmice koja označava početak novog ciklusa, u suprotnom dobivate 0 bodova        """)            with st.expander("💰 Nagrade"):            st.write("""            - Pobednik dobiva nagradu u iznosu od **200 eura** + potpisani dres iznenađenja i dužan je organizirati večeru u roku od mesec dana od završetka prvenstva. Plaća kaznu u iznosu od **20 eura po osobi** koja se ne pojavi na večeri. Kazna se odbija od glavne nagrade i taj prihod ulazi u nagradni fond za sledeće prvenstvo.            """)                elif page == "Prethodni osvajači":    st.markdown("<h3 style='text-align: center;'>🏆 Prethodni osvajači</h3>", unsafe_allow_html=True)    # --- Prvo prvenstvo ---    col1, col2 = st.columns([1, 3])    with col1:        st.image("cirkan.jpg", width=150)    with col2:        st.markdown("""        ### 🥇 World Cup 2022        Pobednik: **Ćirkan**                Prvo takmičenje se uvek pamti, odneo ga je majstor sa 71 bodom, koji je neretko slao tipove na salvetama i papirićima koje su mu konobari dali.        """)                df_round = pd.read_csv("wc2022.csv", header=None, encoding='utf-8-sig')        df_round.columns = ["**Igrači**", "**Bodovi**"]                df_round.index = df_round.index + 1        st.markdown("<h3 style='text-align: center;'>📊 Završna tablica</h3>", unsafe_allow_html=True)        df_round_styled = df_round.style.set_properties(**{'text-align': 'center'})        st.table(df_round_styled)        st.markdown("---")    # --- Drugo prvenstvo ---    col1, col2 = st.columns([1, 3])    with col1:        st.image("organizator.jpg", width=150)    with col2:        st.markdown("""        ### 🥇 Euro 2024        Pobednik: **Organizator**                Takmičenje koje je obeleženo s dosta kontroverznih istupa poraženog Pantera, koji jednostavno nije mogao prihvatiti novo pravilo, a to je bilo tipovanje na pobednika između sebe. Organizator se tu najbolje snašao.        """)                df_round = pd.read_csv("euro2024.csv", header=None, encoding='utf-8-sig')        df_round.columns = ["**Igrači**", "**Bodovi**"]                df_round.index = df_round.index + 1        st.markdown("<h3 style='text-align: center;'>📊 Završna tablica</h3>", unsafe_allow_html=True)        df_round_styled = df_round.style.set_properties(**{'text-align': 'center'})        st.table(df_round_styled)        st.markdown("---")elif page == "Početne predikcije":    df_round = pd.read_csv("predikcije_igraci.csv", header=None, encoding='utf-8-sig')    df_round.columns = ["**Igrači**", "**Prvak**", "**Viceprvak**", "**Trećeplasirani**", "**Strelac**", "**Asistent**", "**Igrač**", "**Golman**", "Pobednik takmičenja"]    st.markdown("<h3 style='text-align: center;'>📊 Individualno</h3>", unsafe_allow_html=True)        df_round.index = df_round.index + 1    df_round_styled = df_round.style.set_properties(**{'text-align': 'center'})    st.table(df_round_styled)            df_round = pd.read_csv("predikcije_grupe.csv", header=None, encoding='utf-8-sig')    df_round.columns = ["**Igrači**", "**Grupa A**", "**Grupa B**", "**Grupa C**", "**Grupa D**", "**Grupa E**", "**Grupa F**", "**Grupa G**", "**Grupa H**", "**Grupa I**","**Grupa J**","**Grupa K**", "**Grupa L**"]            df_round.index = df_round.index + 1    st.markdown("<h3 style='text-align: center;'>📊 Grupe</h3>", unsafe_allow_html=True)    df_round_styled = df_round.style.set_properties(**{'text-align': 'center'})    st.table(df_round_styled)elif page == "Popis igrača po reprezentacijama":    st.markdown("""    <div style='text-align: center; padding: 50px;'>        <h2>🚧 Stranica u izradi</h2>        <p>Ovde će uskoro biti prikazan popis igrača po reprezentacijama.</p>    </div>    """, unsafe_allow_html=True)elif page == "Kolo 1":    st.markdown("""    <div style='text-align: center; padding: 50px;'>        <h2>🚧 Stranica u izradi</h2>        <p>Ovde će uskoro biti prikazani tipovi za prvo kolo.</p>    </div>    """, unsafe_allow_html=True)    elif page == "Kolo 2":    st.markdown("""    <div style='text-align: center; padding: 50px;'>        <h2>🚧 Stranica u izradi</h2>        <p>Ovde će uskoro biti prikazani tipovi za drugo kolo.</p>    </div>    """, unsafe_allow_html=True)    elif page == "Kolo 3":    st.markdown("""    <div style='text-align: center; padding: 50px;'>        <h2>🚧 Stranica u izradi</h2>        <p>Ovde će uskoro biti prikazani tipovi za treće kolo.</p>    </div>    """, unsafe_allow_html=True)    